def min_rest_days(n, activities):
    # dp[i][0] - minimum rest days up to day i if last activity was 'rest'
    # dp[i][1] - minimum rest days up to day i if last activity was 'gym'
    # dp[i][2] - minimum rest days up to day i if last activity was 'contest'
    dp = [[float('inf')] * 3 for _ in range(n)]

    # Base case for the first day
    if activities[0] == 0:
        dp[0][0] = 1  # Rest
    elif activities[0] == 1:
        dp[0][2] = 0  # Contest
    elif activities[0] == 2:
        dp[0][1] = 0  # Gym
    elif activities[0] == 3:
        dp[0][1] = 0  # Gym
        dp[0][2] = 0  # Contest

    for i in range(1, n):
        if activities[i] == 0:
            # Rest
            dp[i][0] = min(dp[i-1][0], dp[i-1][1], dp[i-1][2]) + 1
        elif activities[i] == 1:
            # Contest
            dp[i][2] = min(dp[i-1][0], dp[i-1][1])
        elif activities[i] == 2:
            # Gym
            dp[i][1] = min(dp[i-1][0], dp[i-1][2])
        elif activities[i] == 3:
            # Gym and Contest
            dp[i][1] = min(dp[i-1][0], dp[i-1][2])
            dp[i][2] = min(dp[i-1][0], dp[i-1][1])

    # The answer will be the minimum of resting on the last day
    return min(dp[n-1][0], dp[n-1][1], dp[n-1][2])

